import React, { createContext, useReducer } from 'react'

const initialStore = {
  has_configurations: false,
  inputType: [],
  attributesList: [],
  configurations: {
    user_login_required: false,
    ui_config: {
      header: '',
      content: ''
    }
  },
  form_attributes: [
    {
      id: 0,
      addButton: true,
      deleteButton: false,
      label: '',
      input_type_id: null,
      policy_creation_product_attribute_id: null,
      endorsement_product_attribute_id: null,
      is_editable: false,
      is_required: false,
      placeholder: '',
      input_type_dependencies: null,
      prefilled: null
    }
  ]
}
const store = createContext(initialStore)
const { Provider } = store

const EndorsementProvider = ({ children }) => {
  const [state, dispatch] = useReducer((state, action) => {
    switch (action.type) {
      case 'configure-endorsement':
        return {
          ...state,
          has_configurations: action.payload
        }
      case 'input-types':
        return {
          ...state,
          inputType: action.payload
        }
      case 'update-formData':
        return {
          ...state,
          form_attributes: action.payload
        }
      case 'attribute-update':
        return {
          ...state,
          attributesList: action.payload
        }
      case 'configuration-update':
        return {
          ...state,
          configurations: action.payload
        }
      case 'update-initialState':
        return {
          ...state,
          ...action.payload
        }

      default:
        throw new Error()
    }
  }, initialStore)

  return <Provider value={{ state, dispatch }}>{children}</Provider>
}

export { store, EndorsementProvider }
