import { mapArrayElementsKeysToObjectKeys } from '../../../../../../../helpers/utility'
import actions from './actions'

const INITIAL_STATE = {}

const genericEndorsementDetailReducer = (state, action) => {
  const { payload } = action

  switch (action.type) {
    case actions.RESET_ENDORSEMENT_DETAILS: {
      const stateToBeReset = mapArrayElementsKeysToObjectKeys(payload)
      return { ...state, ...stateToBeReset }
    }
    case actions.INPUT_TYPES:
      return { ...state, ...payload }
    case actions.POLICY_ATTRIBUTES:
      return { ...state, ...payload }
    case actions.GET_COUNTRIES:
      return { ...state, ...payload }
    case actions.GET_ENDORSEMENT_DETAILS:
      return { ...state, ...payload }
    case actions.ADD_ENDORSEMENT_DETAILS:
      return { ...state, ...payload }
    default:
      return state
  }
}

export { INITIAL_STATE }
export default genericEndorsementDetailReducer
