import { useGenericEndorsementContextValue } from '../context/genericEndorsementContext'
import { useServiceRequest } from '@pasarpolis/common-react-hooks'
import actions from '../actions'

export function useResetState () {
  const [, dispatch] = useGenericEndorsementContextValue()
  const resetEndorsementDetails = async (keys = []) => {
    await dispatch(actions.resetState(keys))
  }
  return [resetEndorsementDetails]
}

export const useInputTypeList = () => {
  const [{ inputTypesData }, dispatch] = useGenericEndorsementContextValue()

  const [callApi] = useServiceRequest(dispatch)
  const getInputTypeList = async (payload = {}) => {
    await callApi(actions.getInputTypes(payload))
  }
  // return [{ inputTypesData, inputTypesStatus }, request]
  return {
    getInputTypeList,
    inputTypesData
  }
}

