import { Row, Col, Input } from 'antd'
import { get } from 'lodash'

export default function RadioComponent ({ state, data, dispatch }) {
  const dataSetValue = get(data, 'input_type_dependencies.collection_name', '')

  const updateDataSet = (e) => {
    const currentDataObjectId = get(data, 'id')
    const updateObject = get(state, 'form_attributes', []).map((item) => {
      if (item.id === currentDataObjectId) {
        return {
          ...item,
          input_type_dependencies: {
            ...item.input_type_dependencies,
            collection_name: e.target.value
          }
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: updateObject
    })
  }
  return (
    <Row className='checkbox__required' type='flex' justify='space-around'>
      <Col span={5}>
        <span><b>Data Set</b></span>
      </Col>
      <Col span={16}>
        <Input value={dataSetValue} onChange={updateDataSet} />
      </Col>
    </Row>
  )
}
