import { Row, Col, Checkbox } from 'antd'
import { get } from 'lodash'

export default function FileUpload ({ data, state, dispatch }) {
  const fileUploadObject = get(data, 'input_type_dependencies', {})
  const fileUploadValue = []
  if (get(fileUploadObject, 'multiple_files', null)) {
    fileUploadValue.push('multiple_files')
  }
  const fileType = get(fileUploadObject, 'file_type', []).length > 0 ? get(fileUploadObject, 'file_type', []).split(',') : []
  if (fileType.includes('jpg') || fileType.includes('png')) {
    fileUploadValue.push('jpg,png')
  }
  if (fileType.includes('pdf')) {
    fileUploadValue.push('pdf')
  }

  const onChangeHandler = (values) => {
    const currentDataObjectId = get(data, 'id')
    const updateObject = get(state, 'form_attributes', []).map((item) => {
      if (item.id === currentDataObjectId) {
        return {
          ...item,
          input_type_dependencies: {
            multiple_files: values.includes('multiple_files'),
            file_type: values.filter(item => item !== 'multiple_files').join(',')
          }
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: updateObject
    })
  }
  return (
    <Row className='checkbox__required' type='flex' justify='space-around'>
      <Col span={5}>
        <span><b>File Upload</b></span>
      </Col>
      <Col span={16}>
        <Checkbox.Group value={fileUploadValue} onChange={onChangeHandler}>
          <Checkbox value='multiple_files'>Allow multiple Files</Checkbox>
          <Checkbox value='jpg,png'>images (jpg,png,tiff)</Checkbox>
          <Checkbox value='pdf'>document (pdf)</Checkbox>
        </Checkbox.Group>
      </Col>
    </Row>
  )
}
