/* eslint-disable react-hooks/exhaustive-deps */
import { Row, Col, notification, Spin } from 'antd'
import { useState, useEffect, useContext } from 'react'
import { get, size } from 'lodash'
import styled from 'styled-components'
import { useLoaderContextValue, useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { store } from '../context'
import TopComponent from '../components/topComponent'
import BottomComponent from '../components/bottomComponent'
import ButtonComponent from '../components/buttonContainer'
import { useGetEndorsementDetailsValue } from '../hooks/useGenericEndorsement'
import { payloadData } from '../payloadFormation'

const TopComponentContainer = styled.div`
 padding: 20px 40px 20px 40px;
 border: 1px solid #000;
`

export default function EndorsementPage ({ props, view, productCodeData, packageCode }) {
  const { state, dispatch } = useContext(store)
  const [endorsementFlow, setEndorsementFlow] = useState(false)
  const { getEndorsementDetailsData, getEndorsementDetailsDatas } = useGetEndorsementDetailsValue()
  const [{ GET_ENDORSEMENT_DETAILS_LOADER }] = useLoaderContextValue()
  const [{ getEndorsementDetailsStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  useEffect(() => {
    if (getEndorsementDetailsStatus === 'success') {
      const endorsementData = get(getEndorsementDetailsData, 'data.details', {})
      if (size(endorsementData) === 0) {
        view = 'add'
      }
      const stateData = payloadData(endorsementData)
      dispatch({
        type: 'update-initialState',
        payload: stateData
      })
      resetError(['getEndorsementDetailsStatus'])
    }
    if (getEndorsementDetailsStatus !== 'success' && getEndorsementDetailsStatus !== undefined) {
      notification.error({
        message: get(getEndorsementDetailsData, 'message')
      })
    }
    resetError(['getEndorsementDetailsStatus'])
  }, [getEndorsementDetailsStatus])

  useEffect(() => {
    const switchValue = get(state, 'has_configurations')
    if (switchValue !== endorsementFlow) {
      setEndorsementFlow(switchValue)
    }
  }, [state])

  useEffect(() => {
    getEndorsementDetailsDatas({
      query: {
        product_code: productCodeData,
        package_code: packageCode
      }
    })
  }, [])

  return (
    <TopComponentContainer>
      <Spin tip='Generic Endorsement Loading...' spinning={GET_ENDORSEMENT_DETAILS_LOADER}>
        <Row type='flex' justify='center'>
          <Col span={22}>
            <TopComponent switchValue={endorsementFlow} />
            {
              endorsementFlow &&
                <BottomComponent productCodeData={productCodeData} />
            }
            <ButtonComponent
              props={props}
              productCode={productCodeData}
              packageCode={packageCode}
              view={view}
            />
          </Col>
        </Row>
      </Spin>
    </TopComponentContainer>
  )
}
