import productConfigUrls from '../../../../../../../request/urls/productConfig'

const actions = {
  RESET_ENDORSEMENT_DETAILS: 'RESET_ENDORSEMENT_DETAILS',
  INPUT_TYPES_REQUEST: 'INPUT_TYPES_REQUEST',
  INPUT_TYPES: 'INPUT_TYPES',
  POLICY_ATTRIBUTES_REQUEST: 'POLICY_ATTRIBUTES_REQUEST',
  POLICY_ATTRIBUTES: 'POLICY_ATTRIBUTES',
  GET_COUNTRIES_REQUEST: 'GET_COUNTRIES_REQUEST',
  GET_COUNTRIES: 'GET_COUNTRIES',
  GET_ENDORSEMENT_DETAILS_REQUEST: 'GET_ENDORSEMENT_DETAILS_REQUEST',
  GET_ENDORSEMENT_DETAILS: 'GET_ENDORSEMENT_DETAILS',
  ADD_ENDORSEMENT_DETAILS_REQUEST: 'ADD_ENDORSEMENT_DETAILS_REQUEST',
  ADD_ENDORSEMENT_DETAILS: 'ADD_ENDORSEMENT_DETAILS',

  resetState: (fields = []) => ({
    type: actions.RESET_ENDORSEMENT_DETAILS,
    payload: fields
  }),
  getInputTypes: (payload) => {
    return {
      type: actions.INPUT_TYPES_REQUEST,
      payload: {
        ...payload,
        method: 'GET',
        url: productConfigUrls.inputTypesUrl
      }
    }
  },
  getAttributes: (payload) => {
    return {
      type: actions.POLICY_ATTRIBUTES_REQUEST,
      payload: {
        ...payload,
        method: 'GET',
        url: productConfigUrls.getConfigurableProductDetailattributeUrl
      }
    }
  },
  getCountries: (payload) => {
    return {
      type: actions.GET_COUNTRIES_REQUEST,
      payload: {
        ...payload,
        method: 'GET',
        url: productConfigUrls.getAllProductCountriesUrl
      }
    }
  },
  getEndorsementDetails: (payload) => {
    return {
      type: actions.GET_ENDORSEMENT_DETAILS_REQUEST,
      payload: {
        ...payload,
        method: 'GET',
        url: productConfigUrls.getEndorsementDetails
      }
    }
  },
  addEndorsementDetails: (payload) => {
    return {
      type: actions.ADD_ENDORSEMENT_DETAILS_REQUEST,
      payload: {
        ...payload,
        method: 'POST',
        url: productConfigUrls.addEndorsementDetails
      }
    }
  }
}

export default actions
