/* eslint-disable react-hooks/exhaustive-deps */
import PropTypes from 'prop-types'
import { Row, Col, Input, Checkbox, Select, Icon } from 'antd'
import { get } from 'lodash'
import { store } from '../../context'

import { FieldContainer, DynamicFormContainer } from './dynamicForm.style'
import { useContext, useEffect, useState } from 'react'
import EndorsementDynamicField from './TypesComponent'
const { Option } = Select

export default function DynamicFormComponent (props) {
  const { state, dispatch } = useContext(store)
  const [inputTypes, setInputTypes] = useState([])
  const [policyAttributes, setPolicyAttributes] = useState([])
  const { data } = props

  useEffect(() => {
    if (inputTypes.length === 0) {
      const inputData = get(state, 'inputType', [])
      setInputTypes(inputData)
    }
    if (policyAttributes.length === 0) {
      const policyAttributes = get(state, 'attributesList', []).filter(item => item.attribute_type === 'endorsement')
      setPolicyAttributes(policyAttributes)
    }
  }, [state])

  const inputHandler = (e, id) => {
    const updateObject = get(state, 'form_attributes', []).map((item) => {
      if (item.id === id) {
        return {
          ...item,
          input_type_id: e
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: updateObject
    })
  }

  const endorsementHandler = (e, id) => {
    const updateObject = get(state, 'form_attributes', []).map((item) => {
      if (item.id === id) {
        return {
          ...item,
          endorsement_product_attribute_id: e
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: updateObject
    })
  }

  const remove = (id) => {
    const currentFormData = get(state, 'form_attributes', [])
    let updatedAttributes = []
    if (currentFormData.length > 1) {
      updatedAttributes = currentFormData.filter(item => item.id !== id)
    } else {
      updatedAttributes = currentFormData.map(item => {
        return {
          ...item,
          deleteButton: false
        }
      })
    }
    dispatch({
      type: 'update-formData',
      payload: updatedAttributes
    })
  }

  const add = () => {
    const lastItem = get(state, 'form_attributes', []).map(item => {
      return {
        ...item,
        deleteButton: true
      }
    })
    const newIndex = lastItem[lastItem.length - 1].id + 1

    const newData = {
      id: newIndex,
      addButton: true,
      deleteButton: true,
      label: '',
      input_type_id: null,
      policy_creation_product_attribute_id: null,
      endorsement_product_attribute_id: null,
      is_editable: false,
      is_required: false,
      placeholder: '',
      input_type_dependencies: null,
      prefilled: null
    }
    const newFormAttributes = [...lastItem, newData]
    dispatch({
      type: 'update-formData',
      payload: newFormAttributes
    })
  }

  const labelHandler = (value, id) => {
    const newFormAttributes = get(state, 'form_attributes', []).map(item => {
      if (item.id === id) {
        return {
          ...item,
          label: value
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: newFormAttributes
    })
  }

  const requiredHandler = (values, id) => {
    const newFormAttributes = get(state, 'form_attributes', []).map(item => {
      if (item.id === id) {
        return {
          ...item,
          is_required: values.includes('required'),
          is_editable: values.includes('editable')
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: newFormAttributes
    })
  }
  return (
    <DynamicFormContainer>
      {
        data.length > 0 &&
        data.map((item, index) => {
          const requiredEditableCheckbox = []
          const isEditable = get(item, 'is_editable')
          if (isEditable) {
            requiredEditableCheckbox.push('editable')
          }
          const isRequired = get(item, 'is_required')
          if (isRequired) {
            requiredEditableCheckbox.push('required')
          }
          return (
            <FieldContainer key={index}>
              <Row type='flex' align='middle' gutter={24}>
                <Col span={2}>
                  {
                    item.deleteButton &&
                      <Icon
                        className='dynamic-delete-button button-size'
                        type='minus-circle'
                        theme='filled'
                        onClick={() => remove(item.id)}
                      />
                  }
                </Col>
                <Col span={22}>
                  <Row type='flex' justify='space-around' align='middle'>
                    <Col span={5}>
                      <span><b>Label</b></span>
                    </Col>
                    <Col span={16}>
                      <Input value={item.label} onChange={(e) => labelHandler(e.target.value, item.id)} />
                    </Col>
                  </Row>
                  <Row className='checkbox__required' type='flex' justify='space-around'>
                    <Col span={5} />
                    <Col span={16}>
                      <Checkbox.Group value={requiredEditableCheckbox} onChange={(values) => requiredHandler(values, item.id)}>
                        <Checkbox value='required'>Required</Checkbox>
                        <Checkbox value='editable'>Editable</Checkbox>
                      </Checkbox.Group>
                    </Col>
                  </Row>
                  <Row className='checkbox__required' type='flex' justify='space-around'>
                    <Col span={5}>
                      <span><b>Input Type</b></span>
                    </Col>
                    <Col span={16}>
                      <Select
                        className='select__input_type'
                        showSearch
                        value={item.input_type_id}
                        onChange={(e) => inputHandler(e, item.id)}
                        filterOption={(input, option) =>
                          option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0
                        }
                      >
                        {inputTypes.map((item, index) => (<Option key={index} value={item.id}>{item.name}</Option>))}
                      </Select>
                    </Col>
                  </Row>
                  <Row className='checkbox__required' type='flex' justify='space-around'>
                    <Col span={5}>
                      <span><b>Endorsement Field</b></span>
                    </Col>
                    <Col span={16}>
                      <Select
                        className='select__input_type'
                        showSearch
                        value={item.endorsement_product_attribute_id}
                        onChange={(e) => endorsementHandler(e, item.id)}
                        filterOption={(input, option) =>
                          option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
                      >
                        {policyAttributes.map((item, index) => (<Option key={index} value={item.id}>{item.name}</Option>))}
                      </Select>
                    </Col>
                  </Row>
                  <EndorsementDynamicField data={item} />
                </Col>
              </Row>
            </FieldContainer>
          )
        })
      }
      <Row className='plus-button-row' type='flex' justify='center'>
        <Col>
          <Icon
            className='dynamic-add-button button-size'
            type='plus-circle'
            theme='filled'
            onClick={add}
          />
        </Col>
      </Row>
    </DynamicFormContainer>
  )
}
DynamicFormComponent.defaultProps = {
  data: []
}

DynamicFormComponent.propTypes = {
  data: PropTypes.array
}
