import { Row, Col, Switch } from 'antd'
import { useEffect, useState, useContext } from 'react'

import { TextContainer, SwitchContainer } from './topComponent.style'
import { store } from '../context'

export default function TopComponent ({ switchValue }) {
  const { dispatch } = useContext(store)
  const [value, changeValue] = useState(false)

  useEffect(() => {
    changeValue(switchValue)
  }, [switchValue])

  const onChangeHandler = (checked) => {
    dispatch({
      type: 'configure-endorsement',
      payload: checked
    })
  }
  return (
    <Row type='flex' align='top' gutter={30}>
      <Col span={12}>
        <TextContainer>
          <h3><b>Configure endorsement UI?</b></h3>
          <p>This will enable user to endorse the policy from a UI</p>
        </TextContainer>
      </Col>
      <Col>
        <SwitchContainer>
          <Switch checked={value} onChange={onChangeHandler} />
        </SwitchContainer>
      </Col>
    </Row>
  )
}
