import { Row, Col, Input } from 'antd'
import { get } from 'lodash'

export default function TextComponent ({ data, state, dispatch }) {
  const placeholderValue = get(data, 'placeholder', '')
  const prefilledValue = get(data, 'prefilled', '')

  const updatePlaceholder = (e) => {
    const currentDataObjectId = get(data, 'id')
    const updateObject = get(state, 'form_attributes', []).map((item) => {
      if (item.id === currentDataObjectId) {
        return {
          ...item,
          placeholder: e.target.value
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: updateObject
    })
  }
  const updatePrefilled = (e) => {
    const currentDataObjectId = get(data, 'id')
    const updateObject = get(state, 'form_attributes', []).map((item) => {
      if (item.id === currentDataObjectId) {
        return {
          ...item,
          prefilled: e.target.value
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: updateObject
    })
  }
  return (
    <>
      <Row className='checkbox__required' type='flex' justify='space-around'>
        <Col span={5}>
          <span><b>Prefilled Value</b></span>
        </Col>
        <Col span={16}>
          <Input value={prefilledValue} onChange={updatePrefilled} />
        </Col>
      </Row>
      <Row className='checkbox__required' type='flex' justify='space-around'>
        <Col span={5}>
          <span><b>Placeholder</b></span>
        </Col>
        <Col span={16}>
          <Input value={placeholderValue} onChange={updatePlaceholder} />
        </Col>
      </Row>
    </>
  )
}
