import { get } from 'lodash'

export function payloadData (data) {
  let formAttributes = get(data, 'configurations.form_attributes', [])
  if (formAttributes.length > 0) {
    formAttributes = formAttributes.map((item, index) => {
      return {
        ...item,
        id: index,
        addButton: true,
        deleteButton: formAttributes.length > 1
      }
    })
  } else {
    formAttributes = [{
      id: 0,
      addButton: true,
      deleteButton: false,
      label: '',
      input_type_id: null,
      policy_creation_product_attribute_id: null,
      endorsement_product_attribute_id: null,
      is_editable: false,
      is_required: false,
      placeholder: '',
      input_type_dependencies: null,
      prefilled: null
    }]
  }
  const initialState = {
    has_configurations: get(data, 'has_configurations'),
    inputType: [],
    attributesList: [],
    configurations: {
      user_login_required: get(data, 'configurations.user_login_required'),
      ui_config: get(data, 'configurations.ui_config')
    },
    form_attributes: formAttributes
  }
  return initialState
}

export function payloadDataFormation (data) {
  const payload = {
    has_configurations: get(data, 'has_configurations'),
    configurations: {
      ...get(data, 'configurations', {}),
      form_attributes: get(data, 'form_attributes', []).map(item => {
        return {
          label: item.label,
          input_type_id: item.input_type_id,
          policy_creation_product_attribute_id: item.policy_creation_product_attribute_id,
          endorsement_product_attribute_id: item.endorsement_product_attribute_id,
          is_editable: item.is_editable,
          is_required: item.is_required,
          placeholder: item.placeholder,
          input_type_dependencies: item.input_type_dependencies,
          prefilled: item.prefilled
        }
      })
    }
  }
  return payload
}
