/* eslint-disable react-hooks/exhaustive-deps */
import { useContext, useEffect } from 'react'
import { Row, Col, Button, notification } from 'antd'
import styled from 'styled-components'
import { store } from '../context'
import { get } from 'lodash'
import { payloadDataFormation } from '../payloadFormation'
import { useAddEndorsementDetailsValue } from '../hooks/useGenericEndorsement'
import { useLoaderContextValue, useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'

const ButtonContainer = styled.div`
  padding-top: 20px;
`

export default function ButtonComponent ({ props, productCode, packageCode, view }) {
  const { state } = useContext(store)
  const { addEndorsementDetailsData, addEndorsementData } = useAddEndorsementDetailsValue()
  const { step1Data, step2Data, packageData } = get(props, 'location.state.formData', {})
  const [{ ADD_ENDORSEMENT_DETAILS_LOADER }] = useLoaderContextValue()
  const [{ addEndorsementDetailsStatus }] = useErrorContextValue()
  const { resetError } = useResetError()
  useEffect(() => {
    if (addEndorsementDetailsStatus === 'success') {
      notification.success({
        message: 'Endorsement Detail Posted Successfully'
      })
      if (view === 'add') {
        props.history.push({
          pathname: '/product-config/create-product/3',
          state: {
            formName: 'validation-table',
            formData: {
              step1Data,
              step2Data,
              packageData
            }
          }
        })
      }
      resetError(['addEndorsementDetailsStatus'])
    }
    if (addEndorsementDetailsStatus !== 'success' && addEndorsementDetailsStatus !== undefined) {
      notification.error({
        message: get(addEndorsementDetailsData, 'message')
      })
      resetError(['addEndorsementDetailsStatus'])
    }
  }, [addEndorsementDetailsStatus])

  const submitHandler = (type) => {
    const payloadFormation = payloadDataFormation(state)
    const payload = {
      query: {
        product_code: productCode,
        package_code: packageCode
      },
      body: {
        payload: payloadFormation,
        type: type
      }
    }
    addEndorsementData(payload)
  }
  return (
    <ButtonContainer>
      <Row type='flex' justify='center' gutter={20}>
        {
          view === 'add'
            ? (
              <>
                <Col>
                  <Button onClick={() => props.history.goBack()}> Previous</Button>
                </Col>
                <Col>
                  <Button onClick={() => submitHandler(view)} type='primary'>Next</Button>
                </Col>
              </>
              )
            : (

              <Col>
                <Button
                  loading={ADD_ENDORSEMENT_DETAILS_LOADER}
                  onClick={() => submitHandler(view)}
                  type='primary'
                > Submit
                </Button>
              </Col>
              )
        }
      </Row>
    </ButtonContainer>
  )
}
