import { Row, Col, Input, TreeSelect, Icon } from 'antd'
import { get } from 'lodash'
const { TreeNode } = TreeSelect

function childNode (data) {
  if (data && data.length > 0) {
    return data.map((item, index) => {
      if (item.nested.length === 0) {
        const data = (
          <div>
            <span>{item.name}</span> <br />
          </div>
        )
        return (
          <TreeNode value={item.id} title={data} />
        )
      } else {
        return (
          <TreeNode title={item.name}>
            {childNode(item.nested)}
          </TreeNode>
        )
      }
    })
  }
}

export default function DropDownComponent ({ state, data, dispatch }) {
  const dependencyList = get(state, 'attributesList', []).filter(item => item.attribute_type === 'creation')
  const dataSetValue = get(data, 'input_type_dependencies.collection_name', '')
  const placeholderValue = get(data, 'placeholder', '')
  const dependencyValue = get(data, 'input_type_dependencies.parent_attribute_ids[0]', '')
  const updateDataSet = (e) => {
    const currentDataObjectId = get(data, 'id')
    const updateObject = get(state, 'form_attributes', []).map((item) => {
      if (item.id === currentDataObjectId) {
        return {
          ...item,
          input_type_dependencies: {
            ...item.input_type_dependencies,
            collection_name: e.target.value
          }
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: updateObject
    })
  }

  const updatePlaceholder = (e) => {
    const currentDataObjectId = get(data, 'id')
    const updateObject = get(state, 'form_attributes', []).map((item) => {
      if (item.id === currentDataObjectId) {
        return {
          ...item,
          placeholder: e.target.value
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: updateObject
    })
  }

  const onChangeSelectField = (e) => {
    const currentDataObjectId = get(data, 'id')
    const updateObject = get(state, 'form_attributes', []).map((item) => {
      if (item.id === currentDataObjectId) {
        return {
          ...item,
          input_type_dependencies: {
            ...item.input_type_dependencies,
            parent_attribute_ids: e ? [e] : null
          }
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: updateObject
    })
  }

  const clearHandler = () => {
    const currentDataObjectId = get(data, 'id')
    const updateObject = get(state, 'form_attributes', []).map((item) => {
      if (item.id === currentDataObjectId) {
        return {
          ...item,
          input_type_dependencies: {
            ...item.input_type_dependencies,
            parent_attribute_ids: null
          }
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: updateObject
    })
  }
  return (
    <>
      <Row className='checkbox__required' type='flex' justify='space-around'>
        <Col span={5}>
          <span><b>Data Set</b></span>
        </Col>
        <Col span={16}>
          <Input value={dataSetValue} onChange={updateDataSet} />
        </Col>
      </Row>
      <Row className='checkbox__required' type='flex' justify='space-around'>
        <Col span={5}>
          <span><b>Dependency</b></span>
        </Col>
        <Col span={16}>
          <TreeSelect
            suffixIcon={<Icon type='close-circle' theme='filled' onClick={clearHandler} />}
            className='select__input_type'
            value={dependencyValue}
            onChange={onChangeSelectField}
            treeDefaultExpandAll
          >
            {
              childNode(dependencyList)
            }
          </TreeSelect>
        </Col>
      </Row>
      <Row className='checkbox__required' type='flex' justify='space-around'>
        <Col span={5}>
          <span><b>Placeholder</b></span>
        </Col>
        <Col span={16}>
          <Input value={placeholderValue} onChange={updatePlaceholder} />
        </Col>
      </Row>
    </>
  )
}
