import { useContext } from 'react'
import { Row, Col, Checkbox } from 'antd'
import { get } from 'lodash'
import { BottomContainer, FormContainer } from './BottomContainer.style'
import StaticPart from './endorsementForm/staticPart'
import DynamicContent from './endorsementForm/dynamicForm'
import { store } from '../context'

export default function BottomComponent ({ productCodeData }) {
  const { state, dispatch } = useContext(store)
  const loginHandler = (e) => {
    dispatch({
      type: 'configuration-update',
      payload: {
        ...get(state, 'configurations', {}),
        user_login_required: e.target.checked
      }
    })
  }
  return (
    <BottomContainer>
      <Checkbox checked={get(state, 'configurations.user_login_required')} onChange={loginHandler}> User login required </Checkbox>
      <FormContainer>
        <StaticPart productCodeData={productCodeData} />
        <Row className='dynamic_container' type='flex' justify='center'>
          <Col span={22}>
            <DynamicContent data={get(state, 'form_attributes')} />
          </Col>
        </Row>
      </FormContainer>
    </BottomContainer>
  )
}
