import { Row, Col, Select } from 'antd'
import { get } from 'lodash'

const { Option } = Select
export default function MobileNumberComponent ({ data, state, dispatch, countriesList }) {
  const countryCode = get(data, 'input_type_dependencies.country_id', null)

  const updateMobileNumber = (e) => {
    const currentDataObjectId = get(data, 'id')
    const updateObject = get(state, 'form_attributes', []).map((item) => {
      if (item.id === currentDataObjectId) {
        return {
          ...item,
          input_type_dependencies: {
            country_id: e
          }
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: updateObject
    })
  }
  return (
    <Row className='checkbox__required' type='flex' justify='space-around'>
      <Col span={5}>
        <span><b>Countries</b></span>
      </Col>
      <Col span={16}>
        <Select
          className='select__input_type'
          showSearch
          value={countryCode}
          onChange={updateMobileNumber}
          filterOption={(input, option) =>
            option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
        >
          {countriesList.map((item, index) => (<Option key={index} value={item.id}>{item.code}</Option>))}
        </Select>
      </Col>
    </Row>
  )
}