import React, { createContext, useContext, useReducer } from 'react'
import reducer, { INITIAL_STATE } from '../reducer'

export const GenericEndorsementContext = createContext()

export const GenericEndorsementContextProvider = (props) => {
  return (
    <GenericEndorsementContext.Provider value={useReducer(reducer, INITIAL_STATE)}>
      {props.children}
    </GenericEndorsementContext.Provider>
  )
}

export const useGenericEndorsementContextValue = () => useContext(GenericEndorsementContext)
