/* eslint-disable react-hooks/exhaustive-deps */
import { useEffect, useContext } from 'react'
import { Row, Col, Input, notification } from 'antd'
import { get } from 'lodash'
import styled from 'styled-components'
import { store } from '../../context'
import { useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'
import { useInputTypeList, usePolicyAttributesValue } from '../../hooks/useGenericEndorsement'
const { TextArea } = Input

const StaticContainer = styled.div`
  .staticContainer__label {
    text-align: left;
  }
  .static_part__intro_section{
    margin-top: 10px;
    padding-bottom: 20px;
  }
  border-bottom: 1px dotted #000;
`
export default function StaticPartComponent ({ productCodeData }) {
  const { state, dispatch } = useContext(store)
  const { inputTypesData, getInputTypeList } = useInputTypeList()
  const { policyAttributesData, getPolicyAttributes } = usePolicyAttributesValue()
  const [{ inputTypesStatus, policyAttributesStatus }] = useErrorContextValue()
  const { resetError } = useResetError()

  useEffect(() => {
    if (inputTypesStatus === 'success') {
      dispatch({
        type: 'input-types',
        payload: get(inputTypesData, 'data.details', [])
      })
      resetError(['inputTypesStatus'])
    }
    if (inputTypesStatus !== 'success' && inputTypesStatus !== undefined) {
      notification.error({
        message: get(inputTypesData, 'message')
      })
      resetError(['inputTypesStatus'])
    }
    if (policyAttributesStatus === 'success') {
      dispatch({
        type: 'attribute-update',
        payload: get(policyAttributesData, 'data.details', [])
      })
      resetError(['policyAttributesStatus'])
    }
    if (policyAttributesStatus !== 'success' && policyAttributesStatus !== undefined) {
      notification.error({
        message: get(policyAttributesData, 'message')
      })
      resetError(['policyAttributesStatus'])
    }
  }, [inputTypesStatus, policyAttributesStatus])

  useEffect(() => {
    getInputTypeList()
    getPolicyAttributes({
      query: {
        productCode: productCodeData,
        type: 'creation,endorsement'
      }
    })
  }, [])
  const headerHandler = (e) => {
    dispatch({
      type: 'configuration-update',
      payload: {
        ...get(state, 'configurations', {}),
        ui_config: {
          ...get(state, 'configurations.ui_config', {}),
          header: e.target.value
        }
      }
    })
  }

  const textAreaHandler = (e) => {
    dispatch({
      type: 'configuration-update',
      payload: {
        ...get(state, 'configurations', {}),
        ui_config: {
          ...get(state, 'configurations.ui_config', {}),
          content: e.target.value
        }
      }
    })
  }

  return (
    <StaticContainer>
      <Row type='flex' justify='center' align='middle' gutter={30}>
        <Col span={8} className='staticContainer__label'>
          <span><b>Header</b></span>
        </Col>
        <Col span={10}>
          <Input value={get(state, 'configurations.ui_config.header')} onChange={headerHandler} />
        </Col>
      </Row>
      <Row className='static_part__intro_section' type='flex' justify='center' align='middle' gutter={30}>
        <Col span={8} className='staticContainer__label'>
          <span><b>Intro Paragraph</b></span>
        </Col>
        <Col span={10}>
          <TextArea value={get(state, 'configurations.ui_config.content')} row={5} onChange={textAreaHandler} />
        </Col>
      </Row>
    </StaticContainer>
  )
}