import { Row, Col, Input, Select, Icon } from 'antd'
import { get } from 'lodash'

const { Option } = Select

export default function DateTimeComponent ({ state, data, dispatch, type }) {
  const typeData = get(state, 'inputType', []).filter(item => item.id === type)
  const unitList = get(typeData, '[0].dependency', [])
  const minList = unitList.length > 0 ? unitList.filter(item => item.key === 'min_unit')[0].options : []
  const maxList = unitList.length > 0 ? unitList.filter(item => item.key === 'max_unit')[0].options : []
  const minUnit = get(data, 'input_type_dependencies.min', '')
  const minUnitValue = get(data, 'input_type_dependencies.min_unit', '')
  const maxUnit = get(data, 'input_type_dependencies.max', '')
  const maxUnitValue = get(data, 'input_type_dependencies.max_unit', '')

  const inputHandler = (value, type) => {
    const currentDataObjectId = get(data, 'id')
    const updateObject = get(state, 'form_attributes', []).map((item) => {
      if (item.id === currentDataObjectId) {
        return {
          ...item,
          input_type_dependencies: {
            ...item.input_type_dependencies,
            min: type === 'min' ? value : get(item, 'input_type_dependencies.min'),
            max: type === 'max' ? value : get(item, 'input_type_dependencies.max')
          }
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: updateObject
    })
  }

  const updateUnit = (value, type) => {
    const currentDataObjectId = get(data, 'id')
    const updateObject = get(state, 'form_attributes', []).map((item) => {
      if (item.id === currentDataObjectId) {
        return {
          ...item,
          input_type_dependencies: {
            ...item.input_type_dependencies,
            min_unit: type === 'min' ? value : get(item, 'input_type_dependencies.min_unit'),
            max_unit: type === 'max' ? value : get(item, 'input_type_dependencies.max_unit')
          }
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: updateObject
    })
  }

  const clearHandler = (type) => {
    const currentDataObjectId = get(data, 'id')
    const updateObject = get(state, 'form_attributes', []).map((item) => {
      if (item.id === currentDataObjectId) {
        return {
          ...item,
          input_type_dependencies: {
            ...item.input_type_dependencies,
            min_unit: type === 'min' ? '' : get(item, 'input_type_dependencies.min_unit'),
            max_unit: type === 'max' ? '' : get(item, 'input_type_dependencies.max_unit')
          }
        }
      }
      return item
    })
    dispatch({
      type: 'update-formData',
      payload: updateObject
    })
  }
  return (
    <>
      <Row className='checkbox__required' type='flex' justify='space-around'>
        <Col span={5}>
          <span><b>Min (back date)</b></span>
        </Col>
        <Col span={16}>
          <div className='date_time__container'>
            <Input value={minUnit} onChange={(e) => inputHandler(e.target.value, 'min')} />
            <Select
              suffixIcon={<Icon type='close-circle' theme='filled' onClick={() => clearHandler('min')} />}
              showSearch
              value={minUnitValue}
              onChange={(e) => updateUnit(e, 'min')}
              filterOption={(input, option) =>
                option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
            >
              {minList.map((item, index) => (<Option key={index} value={item}>{item}</Option>))}
            </Select>
          </div>
        </Col>
      </Row>
      <Row className='checkbox__required' type='flex' justify='space-around'>
        <Col span={5}>
          <span><b>Max (future date)</b></span>
        </Col>
        <Col span={16}>
          <div className='date_time__container'>
            <Input value={maxUnit} onChange={(e) => inputHandler(e.target.value, 'max')} />
            <Select
              suffixIcon={<Icon type='close-circle' theme='filled' onClick={() => clearHandler('max')} />}
              showSearch
              value={maxUnitValue}
              onChange={(e) => updateUnit(e, 'max')}
              filterOption={(input, option) =>
                option.props.children.toLowerCase().indexOf(input.toLowerCase()) >= 0}
            >
              {maxList.map((item, index) => (<Option key={index} value={item}>{item}</Option>))}
            </Select>
          </div>
        </Col>
      </Row>
    </>
  )
}