/* eslint-disable react-hooks/exhaustive-deps */
import { notification } from 'antd'
import { get } from 'lodash'
import { store } from '../../../context'
import { useContext, useState, useEffect } from 'react'
import { useGetCountriesValue } from '../../../hooks/useGenericEndorsement'
import TextComponent from './textComponent'
import DateTimeComponent from './dateTimeComponent'
import DropDownComponent from './dropDownComponent'
import MobileNumberComponent from './mobileNumberComponent'
import FileUploadComponent from './fileUpload'
import RadioComponent from './radioComponent'
import { useErrorContextValue, useResetError } from '@pasarpolis/common-react-hooks'

export default function EndorsementType ({ data }) {
  const [countriesList, setCountries] = useState([])
  const { getCountriesData, getCountriesValue } = useGetCountriesValue()
  const [{ getCountriesStatus }] = useErrorContextValue()
  const { resetError } = useResetError()

  useEffect(() => {
    if (getCountriesStatus === 'success') {
      const countriesList = get(getCountriesData, 'data.details', [])
      setCountries(countriesList)
      resetError(['getCountriesStatus'])
    }

    if (getCountriesStatus !== 'success' && getCountriesStatus !== undefined) {
      notification.error({
        message: get(getCountriesData, 'data.detail.message', '')
      })
      resetError(['getCountriesStatus'])
    }
  }, [getCountriesStatus])
  const type = get(data, 'input_type_id')
  useEffect(() => {
    if (type === 3) {
      getCountriesValue()
    }
  }, [type])
  const { state, dispatch } = useContext(store)
  switch (type) {
    case 1:
    case 2: {
      return (
        <TextComponent
          data={data}
          state={state}
          dispatch={dispatch}
        />
      )
    }
    case 3: {
      return (
        <MobileNumberComponent
          state={state}
          data={data}
          dispatch={dispatch}
          countriesList={countriesList}
        />
      )
    }
    case 9:
    case 8: {
      return (
        <DateTimeComponent
          state={state}
          data={data}
          dispatch={dispatch}
          type={type}
        />
      )
    }
    case 7:
    case 4: {
      return (
        <DropDownComponent
          state={state}
          data={data}
          dispatch={dispatch}
        />
      )
    }
    case 5:
      return (
        <FileUploadComponent
          state={state}
          data={data}
          dispatch={dispatch}
        />
      )
    case 6:
      return (
        <RadioComponent
          state={state}
          data={data}
          dispatch={dispatch}
        />
      )

    default: return ''
  }
}
